if (Array.isArray(msg.payload)) {
    var length = msg.payload.length;
    if (length > 1) {
        msg.payload = 1;
    } else if (length === 0) {
        msg.payload = 0;
    } else {
        msg.payload = 1;
    }
} else {
    msg.payload = 0;
}
return msg;

// --- Global Config ---
// Set all external service addresses and parameters here
// This node will run automatically once on startup

// Hailo AI Chip (Face Vector API) Configuration
flow.set('hailo_host', '192.168.10.179');
flow.set('hailo_port', '8000');

// Grove Vision AI Camera Configuration
flow.set('image_width', 640);
flow.set('image_height', 480);

// Grove Vision AI Resolution Configuration (AT+RSL=<width>,<height>)
// For supported resolutions, please refer to the device documentation, e.g., '240,240' or '480,480'
// Reference: https://github.com/Seeed-Studio/SSCMA-Micro/blob/main/docs/protocol/at-protocol-en_US.md
flow.set('resolution', '640,480');

node.log("Global configuration loaded.");

return msg;

// Read environment variables or use default values
const faceEmbedHost = flow.get('hailo_host') || '192.168.10.179';
const faceEmbedPort = flow.get('hailo_port') || '8000';

// Set the API URL to the new all-in-one endpoint
msg.url = `http://${faceEmbedHost}:${faceEmbedPort}/detect_and_embed`;
msg.timeout = 5000; // Set a 5-second timeout

// Prepare the request body, containing only the image
msg.payload = {
    image_base64: msg.payload.img_b64
};

return msg;

// Get face vector
const embedding = msg.payload.vector;
const confidence = msg.payload.confidence;
const processingTime = msg.payload.processing_time_ms;

// Check vector quality
if (confidence < 0.5) {
    node.warn(`Low face quality: ${confidence}`);
    return null;
}

// Device to Collection mapping - add new devices here
const deviceCollectionMap = {
    'grove_vision_ai_v2_eb9e4d18': 'office_entrance',
    'grove_vision_ai_v2_002': 'warehouse_door',
    'grove_vision_ai_v2_003': 'lab_access',
    'default': 'default_faces'
};

// Get device configuration
const deviceId = msg.deviceId;
const collectionName = deviceCollectionMap[deviceId] || deviceCollectionMap['default'];
const threshold = 0.32;  // Similarity threshold, adjustable here

// Prepare FaceEmbed API search request
msg.collectionName = collectionName;
msg.threshold = threshold;
msg.embedding = embedding;
msg.confidence = confidence;
msg.processingTime = processingTime;

// Get Hailo API configuration from flow context
const hailoHost = flow.get('hailo_host') || '192.168.10.179';
const hailoPort = flow.get('hailo_port') || '8000';
msg.url = `http://${hailoHost}:${hailoPort}/vectors/search`;

msg.payload = {
    collection: collectionName,
    vector: embedding,
    threshold: threshold,
    top_k: 1
};

// Set HTTP headers
msg.headers = { 'Content-Type': 'application/json' };

return msg;

const searchResponse = msg.payload;
const deviceId = msg.deviceId;
const threshold = msg.threshold;
const timestamp = new Date().toISOString();

let decision = false;
let name = null;
let similarity = 0.0;
let matchedId = null;

// Check search results from our new API
if (searchResponse && searchResponse.status === 'found' && searchResponse.results.length > 0) {
    const bestMatch = searchResponse.results[0];
    similarity = bestMatch.similarity;

    // The API already filters by threshold, but we can double-check if needed.
    // The check is implicit now: if we have a result, it's a match.
    decision = true;
    name = bestMatch.user_id; // The user_id is the name
    matchedId = bestMatch.id;

}

// Construct result message
const result = {
    ts: timestamp,
    device_id: deviceId,
    decision: decision,
    name: name,
    similarity: parseFloat(similarity.toFixed(4)),
    confidence: msg.confidence,
    processing_time_ms: msg.processingTime,
    matched_id: matchedId
};

// Prepare MQTT publish
msg.topic = `access/result/${deviceId}`;
msg.payload = result;

// Save to context for logging
context.set('lastAccess', result);

return msg;

const result = msg.payload;

// Record access log
node.log(`Access Decision - Device: ${result.device_id}, Decision: ${result.decision}, Name: ${result.name || 'Unknown'}, Distance: ${result.distance}`);

// More detailed logging logic can be added here
// e.g., write to file, database, etc.

return msg;

const payload = msg.payload;
const topic = msg.topic;
const deviceId = topic.split('/')[2];


// Validate enroll request
if (!payload.name || !payload.action || !payload.collection) {
    node.error('Invalid enroll request: missing name, action, or collection');
    return null;
}

if (payload.action === 'start') {
    // Start enrollment process
    msg.deviceId = deviceId;
    msg.enrollName = payload.name;
    msg.payload = {
        action: 'start_collection',
        name: payload.name,
        device_id: deviceId
    };

    // Set enrollment status
    flow.set(`enroll_${deviceId}`, {
        name: payload.name,
        collection: payload.collection, // Store target collection
        status: 'collecting',
        vectors: [], // Initialize vector array
        startTime: Date.now()
    });

    return msg;
}

return null;

// This node listens for subsequent vision frames to collect face data
// In practice, it needs to coordinate with vision_frame_processor

const deviceId = msg.deviceId;
const enrollState = context.get(`enroll_${deviceId}`);

if (!enrollState || enrollState.status !== 'collecting') {
    return null;
}

// Send command to start collection
msg.topic = `access/enroll_status/${deviceId}`;
msg.payload = {
    status: 'collecting',
    message: `Starting to collect face data for ${enrollState.name}, please face the camera`,
    frames_needed: 10
};

return msg;

// Combine Grove Vision AI V2's output 1 (image) and output 2 (detection result)
// Assemble directly into standard vision frame format

const camera_id = msg.camera_id || 'grove_vision_ai_v2_eb9e4d18';

// Determine data source: output 1 is image data (buffer), output 2 is detection result (array)
if (Buffer.isBuffer(msg.payload) || typeof msg.payload === 'string') {
    // Output 1: Raw image data
    context.set(`image_${camera_id}`, {
        img_b64: msg.payload,
        timestamp: Date.now()
    });

    // Image data is not output directly, waits for detection result
    return null;

} else if (Array.isArray(msg.payload)) {
    // Output 2: Detection result - combine image and bounding boxes
    const bboxes = msg.payload;

    // Get corresponding image data
    const imageContext = context.get(`image_${camera_id}`);
    if (!imageContext) {
        node.warn('No image data found for camera: ' + camera_id);
        return null;
    }

    // Check if image data is expired (older than 3 seconds)
    if (Date.now() - imageContext.timestamp > 3000) {
        node.warn('Image data too old for camera: ' + camera_id);
        context.set(`image_${camera_id}`, null);
        return null;
    }

    // Convert Grove Vision AI V2's bbox format to standard format
    // Grove format: [x_center, y_center, width, height, confidence, class]
    const convertedBboxes = [];
    if (Array.isArray(bboxes)) {
        for (const bbox of bboxes) {
            if (bbox.length < 5) continue;

            const x_center = bbox[0];
            const y_center = bbox[1];
            const width = bbox[2];
            const height = bbox[3];
            const confidence = bbox[4];

            // Convert from center coordinates to top-left coordinates
            const x_topleft = x_center - width / 2;
            const y_topleft = y_center - height / 2;

            // --- Bounding box correction logic (fixed floating point error issue) ---
            const maxImageWidth = flow.get('image_width') || 480;
            const maxImageHeight = flow.get('image_height') || 480;

            // 1. Calculate the original four floating-point boundaries
            const left = x_topleft;
            const top = y_topleft;
            const right = x_topleft + width;
            const bottom = y_topleft + height;

            // 2. Clamp the boundaries to the image dimensions, then round to integers for safety
            const final_left = Math.round(Math.max(0, left));
            const final_top = Math.round(Math.max(0, top));
            const final_right = Math.round(Math.min(maxImageWidth, right));
            const final_bottom = Math.round(Math.min(maxImageHeight, bottom));

            // 3. Calculate the final integer x, y, w, h from the corrected integer boundaries
            const final_x = final_left;
            const final_y = final_top;
            const final_w = final_right - final_left;
            const final_h = final_bottom - final_top;

            // 4. Re-check for valid size (skip if width or height is <= 0 after clipping)
            if (final_w <= 0 || final_h <= 0) {
                node.warn(`Bbox has zero size after clipping, skipping. Original: [${bbox.join(', ')}]`);
                continue;
            }

            const score = confidence / 100.0; // Convert to 0-1 range

            convertedBboxes.push({
                x: final_x,
                y: final_y,
                w: final_w,
                h: final_h,
                score: score
            });
        }
    }

    const standardPayload = {
        ts: new Date().toISOString(),
        img_b64: imageContext.img_b64,
        bboxes: convertedBboxes
    };

    msg.deviceId = camera_id;
    msg.topic = `vision/frames/${camera_id}`;
    msg.payload = standardPayload;

    context.set(`image_${camera_id}`, null);

    return msg;

} else {
    return null;
}

// Check if `msg.payload.bboxes` array exists and is not empty
if (msg.payload && Array.isArray(msg.payload.bboxes) && msg.payload.bboxes.length > 0) {
    // If there is a detection result, pass the message to the next node
    return msg; 
} else {
    // If no target is detected, abort the flow and do not return any message
    node.warn("No target detected, API call aborted.");
    return null; 
}

// Handle detection trigger signal from Grove Vision AI V2
// Can be used for statistics, logging, etc.

const camera_id = msg.camera_id || 'unknown';
const detected = msg.payload;

if (detected) {
    node.log(`Face detected by camera: ${camera_id}`);

    // Update detection statistics
    const stats = context.get('detection_stats') || {};
    const today = new Date().toDateString();

    if (!stats[today]) {
        stats[today] = {};
    }
    if (!stats[today][camera_id]) {
        stats[today][camera_id] = 0;
    }

    stats[today][camera_id]++;
    context.set('detection_stats', stats);
}

return null;  // Do not propagate the message

const results = msg.payload;

// Check if the API returned a valid array of faces
if (!Array.isArray(results) || results.length === 0) {
    // If no face is detected, terminate the flow
    return null; 
}

let largestFace = null;
let maxArea = 0;

for (const face of results) {
    const bbox = face.bbox;

    // Fix: Check if bbox is an object containing x,y,w,h
    if (bbox && typeof bbox.x === 'number' && typeof bbox.y === 'number' && typeof bbox.w === 'number' && typeof bbox.h === 'number') {
        const area = bbox.w * bbox.h;
        if (area > maxArea) {
            maxArea = area;
            largestFace = face;
        }
    } else {
        node.warn(`Received incorrect bbox format: ${JSON.stringify(bbox)}`);
    }
}

if (!largestFace) {
    node.warn("No valid bounding box in detected face data.");
    return null;
}

// Fix: Correctly extract nested data from API response
const newMsg = {
    ...msg,
    payload: {
        embedding: largestFace.embedding.vector,
        bbox: largestFace.bbox,
        landmarks: largestFace.landmarks,
        // Prepare data for the next node
        vector: largestFace.embedding.vector,
        confidence: largestFace.embedding.confidence,
        processing_time_ms: largestFace.embedding.processing_time_ms,
        detection_confidence: largestFace.detection_confidence
    },
    originalImage: msg.originalImage || msg.payload.image_base64
};

// Determine if it's a recognition or enrollment flow based on context
const deviceId = msg.deviceId;
const enrollState = flow.get('enroll_' + deviceId);

if (enrollState && enrollState.status === 'collecting') {
    return [null, newMsg];
} else {
    return [newMsg, null];
}

const deviceId = msg.deviceId;
const enrollState = flow.get('enroll_' + deviceId);

if (!enrollState || enrollState.status !== 'collecting') {
    node.warn('Not in collecting state, ignoring vector.');
    return null;
}

// 1. Collect vectors
const vector = msg.payload.vector;
if (vector) {
    enrollState.vectors.push(vector);
}
flow.set('enroll_' + deviceId, enrollState);

const collectedCount = enrollState.vectors.length;
const neededCount = 10;

// 2. Send progress update
const statusUpdate = {
    topic: `access/enroll_status/${deviceId}`,
    payload: {
        status: 'collecting',
        message: `Collecting face data... (${collectedCount}/${neededCount})`,
        collected: collectedCount,
        needed: neededCount
    }
};

// If not fully collected, just send progress and stop
if (collectedCount < neededCount) {
    return [statusUpdate, null];
}

// --- If collection is complete, start processing --- 
node.log(`Collected ${neededCount} vectors for ${enrollState.name}. Averaging and preparing...`);
enrollState.status = 'saving';
flow.set('enroll_' + deviceId, enrollState);

// 3. Calculate average vector
const vectors = enrollState.vectors;
const vectorDim = vectors[0].length;
const avgVector = new Array(vectorDim).fill(0);

for (const v of vectors) {
    for (let i = 0; i < vectorDim; i++) {
        avgVector[i] += v[i];
    }
}
for (let i = 0; i < vectorDim; i++) {
    avgVector[i] /= vectors.length;
}

// 4. Prepare request for our new /vectors/add endpoint
const hailoHost = flow.get('hailo_host') || '192.168.10.179';
const hailoPort = flow.get('hailo_port') || '8000';
const collectionName = enrollState.collection;

if (!collectionName) {
    node.error(`Enrollment for ${enrollState.name} failed: Collection name not found in context.`);
    const errorMsg = {
        topic: `access/enroll_status/${deviceId}`,
        payload: { status: 'error', message: 'Enrollment failed: Target database (collection) not specified.' }
    };
    flow.set('enroll_' + deviceId, null); // Clean up state
    return [errorMsg, null]; // Send error and stop
}

// Prepare the message for the HTTP request node
const addVectorMsg = { ...msg }; // Inherit properties
addVectorMsg.url = `http://${hailoHost}:${hailoPort}/vectors/add`;
addVectorMsg.method = 'POST';
addVectorMsg.headers = { 'Content-Type': 'application/json' };
addVectorMsg.payload = {
    collection: collectionName,
    user_id: enrollState.name,
    vector: avgVector
};

const finalStatusUpdate = {
    topic: `access/enroll_status/${deviceId}`,
    payload: {
        status: 'saving',
        message: 'Data collection complete, saving to database...'
    }
};

// Output 1: MQTT status update
// Output 2: HTTP request to add vector
return [finalStatusUpdate, addVectorMsg];

const deviceId = msg.deviceId;
const enrollState = flow.get('enroll_' + deviceId);
let finalMessage;

// Check the response from our /vectors/add endpoint
if (msg.statusCode === 200 && msg.payload.status === 'success') {
    finalMessage = {
        status: 'success',
        message: `User ${enrollState.name} enrolled successfully!`
    };
    node.log(`Enrollment success for ${enrollState.name}.`);
} else {
    const errorDetail = msg.payload.detail || JSON.stringify(msg.payload);
    finalMessage = {
        status: 'error',
        message: `User ${enrollState.name} enrollment failed: ${errorDetail}`
    };
    node.error(`Enrollment failed: ${errorDetail}`);
}

// Clean up context
flow.set('enroll_' + deviceId, null);

msg.topic = `access/enroll_status/${deviceId}`;
msg.payload = finalMessage;

return msg;

// Get the resolution string from global config, e.g., '240,240' or '480,480'
const resolution = flow.get('resolution') || '240,240';
// Get device ID from trigger message
const deviceId = msg.topic || 'grove_vision_ai_v2_eb9e4d18';

// --- Resolution to OPT_ID Mapping ---
// !!Important!!: This mapping is inferred from common practice, you need to confirm the correct OPT_ID from the full device documentation
// AT+SENSOR=<SENSOR_ID,ENABLE/DISABLE,OPT_ID>\r\n
// Reference: https://github.com/Seeed-Studio/SSCMA-Micro/blob/main/docs/protocol/at-protocol-en_US.md
const resolutionMap = {
    '240,240': 0, // Assuming OPT_ID 0 is 240x240
    '480,480': 1,  // Assuming OPT_ID 1 is 480x480 (needs verification)
    '640,480': 2
};

const opt_id = resolutionMap[resolution];
if (typeof opt_id === 'undefined') {
    node.error(`Unsupported resolution config: ${resolution}`);
    return null;
}

// Construct MQTT topic for sending AT command
const commandTopic = `sscma/v0/${deviceId}/rx`;

// Construct AT command to set sensor (sensor_id=1, enable=1)
const atCommand = `AT+SENSOR=1,1,${opt_id}\r\n`;

node.log(`Preparing to send command to ${commandTopic}: ${atCommand}`);

msg.topic = commandTopic;
// Convert the string command to the Buffer format required by the device
msg.payload = Buffer.from(atCommand);

return msg;

// Get collection and name from input
const collection = msg.payload.collection;
const nameToDelete = msg.payload.name;

if (!collection || !nameToDelete) {
    node.error("Delete failed: 'collection' and 'name' must be provided in the input", msg);
    return null;
}

// Get Hailo API configuration from flow context
const hailoHost = flow.get('hailo_host') || '192.168.10.179';
const hailoPort = flow.get('hailo_port') || '8000';

// Set API endpoint for our new delete endpoint
msg.url = `http://${hailoHost}:${hailoPort}/vectors/delete`;

// This is a POST request
msg.method = 'POST';

// Build the payload
msg.payload = {
    collection: collection,
    user_id: nameToDelete
};

// Set HTTP headers
msg.headers = { 'Content-Type': 'application/json' };

node.log(`Preparing to delete data for user '${nameToDelete}' from collection '${collection}'`);

return msg;

function getJpegSize(buffer) {
    let i = 2; // Skip the JPEG header (0xFFD8)
    while (i < buffer.length) {
        if (buffer[i] !== 0xFF) {
            break;
        }

        const marker = buffer[i + 1];
        const length = buffer.readUInt16BE(i + 2);

        // Start Of Frame markers (not all SOF markers, but common ones)
        if (marker === 0xC0 || marker === 0xC2) {
            const height = buffer.readUInt16BE(i + 5);
            const width = buffer.readUInt16BE(i + 7);
            return { width, height };
        }

        i += 2 + length;
    }
    return null;
}

// Step 1: Parse base64 to Buffer
const base64 = msg.payload.replace(/^data:image\/\w+;base64,/, '');
const buffer = Buffer.from(base64, 'base64');

// Step 2: Get dimensions
const size = getJpegSize(buffer);
if (size) {
    msg.payload = size;
} else {
    msg.payload = { error: "Could not parse JPEG dimensions" };
}
return msg;
